/* =====================================================================
   NOVIDADES DE CADA VERSÃO (zzz131) — o "o que mudou" que a equipe lê.

   Esta lista vai JUNTO com o sistema: toda versão que muda algo que a
   equipe percebe ganha um registro aqui, escrito na hora de publicar a
   versão. Ninguém precisa cadastrar nada: atualizou o B7, o cartão de
   novidades aparece sozinho (js/sistema.js → B7.Novidades).

   Como escrever um registro:
     · só o que muda para QUEM USA, em frase curta e sem termo técnico;
     · nada de banco, teste, correção interna ou ressalva — isso é do
       relatório, não daqui;
     · versão que não muda nada visível não entra;
     · o que é só do administrador NÃO entra (Kevin, 09/10/2026: aqui é
       só o que interessa à equipe) — isso ele lê no relatório;
     · a mais nova em cima.

   Quem vê cada registro (todos opcionais; sem nenhum = toda a equipe):
     funcao: 'videomaker'   só quem tem essa função (administrador também vê)
     rota: 'oportunidades'  só quem abre essa tela
     recurso: 'ia_voz'      só se o recurso estiver liberado para a pessoa
     ia: 'chat'             só se essa parte da IA estiver ligada
   O Portal do cliente não recebe novidades.
   ===================================================================== */
window.B7 = window.B7 || {};

B7.NOVIDADES_VERSOES = [
  { id: 'v-zzz297', versao: 'zzz297', em: '2026-10-29T16:00:00-03:00',
    titulo: 'Mensagens chegam como no WhatsApp: responda pela própria notificação',
    itens: ['No app Android, a mensagem chega com a foto e o nome de quem mandou e as mensagens ainda não lidas, uma embaixo da outra.',
            'Toque em Responder e escreva ali mesmo, sem abrir o B7. Também dá para Marcar como lida ou Silenciar a conversa por 8 horas.',
            'No navegador, a notificação também mostra quem mandou e a mensagem, com Marcar como lida e Responder.',
            'Atualize o app Android para a versão nova para ver o aviso novo.'] },
  { id: 'v-zzz296', versao: 'zzz296', em: '2026-10-29T14:00:00-03:00',
    titulo: 'Esqueceu a senha? Agora dá para criar uma nova sozinho',
    itens: ['Na tela de entrada, toque em “Esqueci minha senha”: chega um código no seu e-mail e você cria uma senha nova na hora.',
            'Para isso, cadastre o seu e-mail de recuperação: menu da sua foto → Meu perfil → Segurança → E-mail de recuperação.',
            'Quando a senha é trocada assim, você recebe um aviso por e-mail e as sessões abertas em outros aparelhos são encerradas.'] },
  { id: 'v-zzz280', versao: 'zzz280', em: '2026-10-29T06:00:00-03:00',
    titulo: 'Retrospectiva do mês: o mês da B7 contado em histórias',
    itens: ['Igual à retrospectiva do Spotify: o mês em telas cheias, com quantos vídeos, artes e posts saíram, os bastidores, o dia mais corrido e quantas vezes os clientes disseram “aprovado”.',
            'No fim, o seu mês: o que você entregou e quanto saiu no prazo.',
            'Abra pelo botão ✨ Meu mês no seu perfil, no Panorama ou, no programa do Windows, apertando Alt. No começo de cada mês ela chega sozinha.'] },
  { id: 'v-zzz279', versao: 'zzz279', em: '2026-10-29T05:00:00-03:00',
    titulo: 'Legendas mais fácil, barra de rolagem nova e o programa do Windows com a cara do B7',
    itens: ['A tela de Legendas ficou em passos: escolha o cliente, arraste o .srt (ou cole o texto) e veja quantas legendas e quanto tempo antes de mandar para a IA.',
            'A barra de rolagem agora é fina e arredondada, em todas as telas.',
            'Ao ligar o Google (Agenda ou conta), a tela de volta agora é bonita e fecha sozinha.',
            'No programa do Windows, os avisos de atualização e o menu do Alt agora têm a cara do B7, tudo em português.'] },
  { id: 'v-zzz278', versao: 'zzz278', em: '2026-10-29T04:00:00-03:00',
    titulo: 'Legendas: a IA conserta a legenda do vídeo',
    rota: 'legendas',
    itens: ['Nova aba Legendas: arraste o .srt (ou cole o texto), escolha o cliente e a IA conserta ortografia, acento, maiúscula, pontuação, %, R$ e o nome das marcas — sem reescrever o que foi falado.',
            'Os tempos e a numeração nunca mudam. Você vê o antes e depois de cada legenda e pode desfazer qualquer correção.',
            'Baixe o .srt corrigido pronto para o editor. Fica guardado no Histórico e, se veio de uma demanda de edição, na própria demanda.',
            'Em “Marcas e termos” fica a grafia oficial das marcas (lista geral) e os termos de cada cliente.'] },
  { id: 'v-zzz277', versao: 'zzz277', em: '2026-10-29T03:00:00-03:00',
    titulo: 'A IA monta as demandas de edição a partir dos roteiros',
    rota: 'video', ia: 'chat',
    itens: ['Na tela da gravação, “✨ Demandas de edição com IA” lê os roteiros e prepara uma demanda para cada vídeo: título curto, resumo para quem edita e prazo (3 dias úteis depois da gravação).',
            'Você confere, ajusta o título, o resumo, o prazo e quem edita, e só então confirma. Roteiro que já tem demanda não entra de novo.',
            'Ao concluir uma gravação, o aviso já oferece “Gerar demandas com IA”.'] },
  { id: 'v-zzz276', versao: 'zzz276', em: '2026-10-29T02:00:00-03:00',
    titulo: 'Cliente avulso: cadastro mais simples',
    rota: 'clientes',
    itens: ['Ao marcar o contrato como Avulso, o campo “Como trabalhamos com este cliente” some: no avulso, o que vale é o projeto.'] },
  { id: 'v-zzz275', versao: 'zzz275', em: '2026-10-29T01:30:00-03:00',
    titulo: 'Apagar várias demandas de uma vez',
    itens: ['Na Edição de vídeo, no Design e na Produção, selecione as demandas (Ctrl ou Shift + clique) e use “Apagar” na barra de baixo. Na Edição de vídeo também dá pelo botão direito.',
            'O que for apagado vai para a Lixeira — dá para desfazer na hora, no aviso, ou restaurar depois por lá.',
            'Na Produção, agora dá para selecionar várias demandas também (Ctrl ou Shift + clique).'] },
  { id: 'v-zzz274', versao: 'zzz274', em: '2026-10-29T00:30:00-03:00',
    titulo: 'Projetos avulsos: o cliente que compra um vídeo ou uma edição',
    rota: 'projetos',
    itens: ['Cliente agora tem contrato Mensal ou Avulso (Editar cliente). Avulso é quem comprou um trabalho pontual e não usa o portal.',
            'Novo projeto avulso (no botão Criar ou na página do cliente), em três tipos: vídeo completo (roteiro, gravação e edição), cliente grava (a B7 faz roteiro e edição) ou só edição.',
            'Ao criar, o sistema já monta o roteiro, a gravação e as demandas de edição. A edição fica esperando até a gravação acontecer ou o material chegar pelo Drive.',
            'O roteiro vai para o cliente pelo WhatsApp (texto pronto ou PDF); quando ele aprovar, é só marcar "Cliente aprovou o roteiro". "Material recebido" libera a edição.',
            'Cada projeto mostra a linha do tempo e o próximo passo. As demandas de vídeo dele ganham a etiqueta "Avulso".'] },
  { id: 'v-zzz273', versao: 'zzz273', em: '2026-10-28T23:00:00-03:00',
    titulo: 'Entrar com Google também no programa do Windows',
    itens: ['No programa do Windows, "Entrar com Google" e "Vincular conta Google" abrem o Google no navegador do computador; depois de escolher a conta, o programa entra sozinho.',
            'Precisa da versão nova do programa: ela chega pela atualização automática (ou em Ajuda → Procurar atualização).'] },
  { id: 'v-zzz272', versao: 'zzz272', em: '2026-10-28T22:00:00-03:00',
    titulo: 'Política de Privacidade e Termos de Serviço',
    itens: ['O Sistema B7 agora tem Política de Privacidade (de acordo com a LGPD e com as regras do Google) e Termos de Serviço, em páginas públicas com link fixo.',
            'Os links aparecem no pé da tela de login.'] },
  { id: 'v-zzz271', versao: 'zzz271', em: '2026-10-28T21:00:00-03:00',
    titulo: 'Correções: bolinha do status e tela de carregamento',
    itens: ['A bolinha do status no perfil (barra lateral e painel) ficava amassada em cima da foto. Agora fica redonda, no canto.',
            'A frase "Preparando o seu espaço…" ficava em cima das faixas claras da abertura e não dava para ler. Agora tem uma placa escura atrás.',
            'Meu perfil → Segurança: o cartão "Entrar com Google" agora explica por que não dá para vincular (no app, só pelo navegador; ou o Google ainda não foi ativado no servidor) em vez de sumir.'] },
  { id: 'v-zzz270', versao: 'zzz270', em: '2026-10-28T20:00:00-03:00',
    titulo: 'Sua conta na barra lateral, status da equipe e "Visualizar como" para clientes',
    itens: ['No computador, a sua conta agora fica no pé da barra lateral: foto, nome e status. Tocando abre o painel com Meu status, Meu dia (para hoje, atrasadas, gravações de hoje), tema e atalhos.',
            'Status: Disponível, Em gravação, Em reunião, Ausente ou Não perturbe, com um recado curto. No "Não perturbe" os avisos ficam guardados no sino, sem som, e chega um resumo quando você volta.',
            'Visualizar como (administradores): escolha alguém da equipe ou uma pessoa de um cliente e decida entre "Só visualizar" (nada é salvo) ou "Entrar na conta" (age como a pessoa, fica registrado).',
            'Trocar de conta e voltar para a sua agora é direto, sem a abertura e sem a tela de carregamento.'] },
  { id: 'v-zzz269', versao: 'zzz269', em: '2026-10-28T18:00:00-03:00',
    titulo: 'Permissões ação por ação, acesso que vale na hora e chamado em tempo real',
    itens: ['Configurações → Funções e permissões → "O que cada um pode fazer": liga e desliga cada ação (criar gravação, criar demanda de design, mover no quadro, enviar para o cliente…) por função ou só para uma pessoa. O banco obedece de verdade.',
            'Acesso liberado vale na hora: quando a administração aprova um pedido ou muda uma permissão, o menu e a tela da pessoa se atualizam sozinhos, sem sair e entrar.',
            'Corrigido: com o módulo Produção (quadro) liberado, a pessoa continuava vendo o quadro vazio. Agora aparece e funciona. O mesmo para Edição de vídeo liberada a quem não é videomaker.',
            'Gravações: o videomaker com Gravações em Editar ou Total agora vê o botão "Nova gravação" também na tela de Gravações (antes só no Calendário).',
            'Botões de criar só aparecem para quem pode usar; se o sistema recusar, a mensagem diz onde pedir a liberação.',
            'Chamados: a conversa atualiza em tempo real dos dois lados — a mensagem aparece na hora, sem esperar.',
            'Para a equipe, o menu fala de produção: "Meu dia", "Meu trabalho" e "Produção da equipe".'] },
  { id: 'v-zzz268', versao: 'zzz268', em: '2026-10-24T20:00:00-03:00',
    titulo: 'Comunicação com o cliente: e-mail semanal, recados e WhatsApp',
    itens: ['Resumo semanal por e-mail: no portal (Meu perfil) o cliente informa o e-mail e recebe toda segunda de manhã o que foi aprovado, o que espera por ele, o que vai ao ar e as gravações — num e-mail com a cara da Branding7. Semana vazia não manda nada.',
            'Recados: em Gestão → Recados você publica um aviso (feriado, novidade, atenção) para todos os clientes ou para um só, com data para sair. Ele aparece no Início do portal e o cliente pode dispensar.',
            'Aprovações: novo botão "Avisar no WhatsApp" — abre o grupo do cliente com a mensagem pronta e o link direto para aprovar.'] },
  { id: 'v-zzz267', versao: 'zzz267', em: '2026-10-24T18:00:00-03:00',
    titulo: 'IA: sete ferramentas novas',
    itens: ['Ata de reunião com IA (botão Criar): grave a reunião ou envie o áudio e receba resumo, decisões e tarefas com responsável e prazo.',
            'Legenda a partir da arte: a IA olha a arte, segue o tom do cliente e sugere duas legendas com hashtags. Também no Design, nas peças aprovadas ("✨ Legenda com IA").',
            'Revisar na voz da marca: cole um texto e a IA dá nota de aderência, aponta o que ajustar e entrega a versão sugerida.',
            'Kanban: no feedback do cliente, "✨ Virar tarefas com IA" transforma os comentários em tarefas e adiciona como notas internas.',
            'Gestão: "O que olhar primeiro?" — a IA lê a saúde dos clientes e diz por onde começar, com uma ação para cada cliente em risco.',
            'Portal: no pedido, "✨ Conferir com a IA" aponta o que falta (tamanho, textos, preço, data) para a equipe acertar de primeira.',
            'Assistente: nova sugestão "Datas da semana" com ideias de post para cada cliente.'] },
  { id: 'v-zzz266', versao: 'zzz266', em: '2026-10-24T16:00:00-03:00',
    titulo: 'Gestão: o painel do dono da agência',
    itens: ['Nova tela "Gestão" (só administrador, no grupo Principal) com três abas.',
            'Visão geral: clientes ativos, entregas do mês (e o ritmo comparado ao mês passado), entregas atrasadas, aprovações com o cliente, pedidos e a satisfação do mês, mais o gráfico de entregas dos últimos 6 meses.',
            'Saúde dos clientes: um semáforo por cliente (nota de 0 a 100) com os motivos — atrasos, aprovação parada, demora para responder, muitas peças voltando com ajuste, nota baixa na pesquisa e meses sem entregas.',
            'Pedidos: o que os clientes pediram pelo portal, quanto tempo levou até ficar pronto e quem mais pede.'] },
  { id: 'v-zzz265', versao: 'zzz265', em: '2026-10-24T14:00:00-03:00',
    titulo: 'Portal: calendário do mês e pesquisa de satisfação',
    itens: ['Portal do cliente: nova tela "Calendário" com o mês inteiro — o que vai ao ar em cada dia (com a miniatura da arte, quando há) e as gravações marcadas. No celular vira uma agenda por dia. Tocar num item com aprovação abre a revisão.',
            'Pesquisa de satisfação: a partir do dia 20, o cliente vê no Início "De 0 a 10, quanto você recomendaria a Branding7 este mês?", com comentário opcional.',
            'A coordenação recebe um aviso a cada resposta — nota de 0 a 6 chega como "Atenção".'] },
  { id: 'v-zzz264', versao: 'zzz264', em: '2026-10-24T12:00:00-03:00',
    titulo: 'As respostas da IA ficaram muito mais bonitas',
    itens: ['O Assistente, o Suporte (da equipe e do portal do cliente) e o "O que rolou aqui?" do WhatsApp agora respondem com blocos visuais: destaques coloridos (dica, atenção, resolvido, urgente), números em cartões, passos numerados, listas de checagem, cartões por cliente, tabelas e marca-texto.',
            'A resposta entra na tela bloco por bloco, com uma animação suave.',
            'A IA pode colocar botões que levam direto para a tela certa do B7 (ex.: "Abrir o Kanban").',
            '"Copiar" e "Ouvir" continuam entregando o texto limpo, sem as marcações. Textos para publicar ou mandar no WhatsApp seguem simples.'] },
  { id: 'v-zzz263', versao: 'zzz263', em: '2026-10-24T10:00:00-03:00',
    titulo: 'Pedidos do cliente e lembrete de aprovação',
    itens: ['Portal do cliente: nova tela "Pedidos". O cliente pede algo novo (arte, vídeo, post, texto) com detalhes e data, e acompanha: Recebido → Em produção → Pronto.',
            'Cada pedido vira um cartão no Kanban, marcado "Pedido do cliente", e a coordenação recebe um aviso na hora.',
            'Quando a equipe move o cartão, o pedido muda sozinho no portal e quem pediu é avisado quando começa e quando fica pronto.',
            'Lembrete automático: em dia útil, às 10h, o dono e o gestor do cliente recebem "N materiais esperando sua aprovação" quando há material parado há 2 dias ou mais (no máximo a cada 3 dias).',
            'O assistente do Suporte do portal sabe explicar como fazer um pedido.'] },
  { id: 'v-zzz262', versao: 'zzz262', em: '2026-10-23T21:00:00-03:00',
    titulo: 'Pronto para o lançamento: segurança, portal e IA',
    itens: ['Segurança: 50 funções do banco que respondiam até para quem não tinha entrado agora só respondem para quem está logado. As internas (avisos e rotinas) ficaram fechadas para todos.',
            'Mais rápido: novos índices nas tabelas mais usadas e regras de acesso das conversas com a IA calculadas uma vez por consulta, não por linha.',
            'Mensagens de erro em português claro: "sem conexão", "sessão expirou", "seu acesso não permite" no lugar de texto técnico — no sistema e no portal do cliente.',
            'Portal do cliente: no primeiro acesso, uma tela de boas-vindas explica onde aprovar, acompanhar a produção, ver gravações, falar com o suporte e (para o Dono) convidar a equipe.',
            'IA: quando o serviço do Google cai por alguns segundos, o B7 tenta de novo até duas vezes antes de mostrar erro.',
            'O assistente do Suporte do portal agora sabe explicar Dono, Gestor e Equipe, como convidar pessoas e como gerar senha nova.'] },
  { id: 'v-zzz261', versao: 'zzz261', em: '2026-10-23T19:00:00-03:00',
    titulo: 'Portal do cliente: Dono, Gestor e Equipe',
    itens: ['Cada pessoa do cliente agora tem um papel em cada empresa: Dono (vê tudo, aprova e cuida da equipe), Gestor (vê tudo e aprova) e Equipe (vê e comenta).',
            'Em Configurações → Pessoas, ao criar ou editar um cliente, você escolhe o papel dele em cada empresa marcada. O "pode aprovar" virou isso.',
            'O Dono tem a tela Equipe no portal: convida pessoas (o sistema cria usuário e senha e já monta a mensagem para mandar no WhatsApp), muda papéis, gera senha nova e tira alguém do portal. A administração recebe um aviso a cada mudança.',
            'Quem entra com a senha recebida vê um aviso pedindo para criar uma senha própria.',
            'Para quem é Equipe, o portal fala "Aguardando aprovação" e "Ver e comentar" em vez de "Aguardando você".'] },
  { id: 'v-zzz260', versao: 'zzz260', em: '2026-10-23T17:00:00-03:00',
    titulo: 'Abertura completa sempre no app',
    itens: ['No app Android, abrir o B7 agora mostra sempre a abertura completa que você escolheu, mesmo que tenha usado há pouco. Ele continua voltando para a tela em que você estava.'] },
  { id: 'v-zzz259', versao: 'zzz259', em: '2026-10-23T16:00:00-03:00',
    titulo: 'Abertura lisa no app Android',
    itens: ['No app, a abertura agora espera o sistema terminar de carregar e só então começa, do início ao fim, sem trancos.',
            'O código do sistema vai compactado dentro do app: o celular lê bem menos ao abrir (cerca de 40% a menos), então abre mais rápido.'] },
  { id: 'v-zzz258', versao: 'zzz258', em: '2026-10-23T15:00:00-03:00',
    titulo: 'Uma abertura só no app Android',
    itens: ['No app, a abertura do Android agora é a mesma abertura do sistema: a que você escolheu em Configurações → Abertura e sons (as 9 opções, com som). Nada de duas aberturas seguidas.',
            'A tela do Android abre direto no céu escuro da abertura e passa para ela sem emenda.'] },
  { id: 'v-zzz257', versao: 'zzz257', em: '2026-10-23T14:00:00-03:00',
    titulo: 'Widget "Hoje no B7" novo',
    itens: ['O widget da tela inicial do Android ganhou a cara da B7: brilho nas cores da marca, símbolo colorido e saudação pelo horário.',
            'Os números vêm com ícone e cor; o de atrasos fica vermelho quando tem atraso e verde quando está tudo em dia. Cada número abre a tela dele.',
            'Embaixo: próxima gravação (ou o alerta de atraso), botão de atualizar e atalhos para Painel, Gravações, Ideia e Prompter.'] },
  { id: 'v-zzz256', versao: 'zzz256', em: '2026-10-23T13:00:00-03:00',
    titulo: 'App Android mais caprichado',
    itens: ['Abertura nova no app: o símbolo da B7 se monta (o bulbo acende, a base sobe e as bolhas saem uma a uma) com a marca Branding7 no rodapé, e a tela só sai quando o sistema já carregou.',
            'Ícone temático: no Android 13 ou mais novo, com "ícones temáticos" ligado, o B7 acompanha as cores do seu celular.',
            'Logos e símbolo da B7 em alta resolução dentro do app: nítidos em qualquer tela.'] },
  { id: 'v-zzz255', versao: 'zzz255', em: '2026-10-23T12:00:00-03:00',
    titulo: 'Pacotes de produção',
    itens: ['Em Configurações → Pacotes de produção, monte o que cada cliente contrata por mês (ex.: 6 cards + 6 carrosséis + 4 reels) e os dias de postagem.',
            'Ao criar uma linha editorial, escolha o pacote: os conteúdos já nascem com o tipo e a data espalhada pelo mês. O último pacote usado com o cliente já vem escolhido na próxima linha.'] },
  { id: 'v-zzz254', versao: 'zzz254', em: '2026-10-23T11:00:00-03:00',
    titulo: 'Relatório do mês',
    itens: ['No Panorama, o botão "Relatório do mês" mostra, para o mês na tela: posts publicados, artes e vídeos entregues, quanto saiu no prazo e quantas aprovações voltaram com ajuste.',
            'Duas visões: por cliente (inclui o tempo médio que o cliente leva para responder) e por pessoa da equipe (entregas, prazo, versões por arte e o que está atrasado hoje). Dá para baixar em planilha.'] },
  { id: 'v-zzz253', versao: 'zzz253', em: '2026-10-23T10:00:00-03:00',
    titulo: 'Prazos que avisam antes',
    itens: ['Peça de design ou vídeo que vence hoje ou amanhã e ainda não começou: quem é responsável recebe um aviso às 9h.',
            'A coordenação recebe um resumo só com tudo o que está em risco (inclusive o que ninguém pegou e os posts de amanhã que ainda estão em ideia), e o Painel mostra "entregas que não começaram" em Precisa da sua atenção.',
            'Continua igual: atrasou, a pessoa é avisada; com 2 dias de atraso a coordenação é chamada; com 5, vira crítico.'] },
  { id: 'v-zzz252', versao: 'zzz252', em: '2026-10-23T09:00:00-03:00',
    titulo: 'Horário de silêncio',
    itens: ['Em Configurações → Notificações, escolha um horário de silêncio: fora dele os avisos ficam guardados no sino, sem push nem som, e quando o silêncio acaba chega um aviso só com o resumo do que aconteceu.',
            'A administração define o expediente da equipe em Configurações → Equipe; cada pessoa pode seguir a equipe, ter o próprio horário ou receber sempre.'] },
  { id: 'v-zzz251', versao: 'zzz251', em: '2026-10-23T04:00:00-03:00',
    titulo: 'Conferência automática de permissões',
    itens: ['Em Configurações → Funções e permissões, a administração vê a "Conferência de segurança": o B7 testa cada pessoa em cada módulo e cada regra do banco e diz se está tudo certo.',
            'A conferência também roda sozinha todo dia de manhã e só avisa a administração se achar algum problema.',
            'Quem não tem permissão para mexer no WhatsApp ou na Agenda da equipe agora recebe um aviso claro, como já acontecia nas outras áreas.'] },
  { id: 'v-zzz250', versao: 'zzz250', em: '2026-10-23T03:00:00-03:00',
    titulo: 'Observações internas ficam só com a equipe',
    itens: ['As observações para o design de cada conteúdo nunca aparecem para o cliente, e as observações dos itens do status semanal só aparecem quando o status foi publicado com "mostrar observações".',
            'O assistente do B7 foi atualizado com a ajuda das telas novas.'] },
  { id: 'v-zzz249', versao: 'zzz249', em: '2026-10-23T02:00:00-03:00',
    titulo: 'Permissões levadas a sério',
    itens: ['O nível de cada pessoa em cada parte do B7 (Ver, Editar ou Total) agora vale de verdade em Clientes, Linhas editoriais, Roteiros, Gravações e Status semanal: quem só pode ver recebe um aviso claro se tentar alterar, em vez de a alteração sumir.',
            'WhatsApp, Lixeira e Agenda e recado da equipe passaram a ser permissões que a administração pode dar ou tirar de cada função ou pessoa.'] },
  { id: 'v-zzz248', versao: 'zzz248', em: '2026-10-23T01:00:00-03:00',
    titulo: 'Repasse de trabalho entre a equipe',
    itens: ['Quando alguém sai da equipe ou vai ficar um tempo fora, a administração pode passar o que estava com a pessoa (peças de design, demandas de vídeo, gravações marcadas e cards da Produção) para outras pessoas.',
            'Quem recebe ganha um aviso só, com o total do que chegou, e o histórico de cada item mostra de quem ele veio.'] },
  { id: 'v-zzz247', versao: 'zzz247', em: '2026-10-23T00:00:00-03:00',
    titulo: 'Equipe: recado fixo, ausências e aniversários',
    itens: ['Recado da administração: quando houver, aparece um cartão no alto da tela com o aviso da semana. Feche o seu quando quiser.',
            'Aniversários: no dia, aparece um cartão com o botão "Mandar parabéns", que abre a conversa com o aniversariante. E quem faz aniversário ganha um cartão só dele.',
            'Férias, folgas e atestados: quem estiver fora aparece marcado no cartão de Pessoas e acessos.'] },
  { id: 'v-zzz246', versao: 'zzz246', em: '2026-10-22T23:00:00-03:00',
    titulo: 'Correções nas Notificações e nos envios pelo celular',
    itens: ['Com uma cor do sistema escolhida e o tema escuro, algumas caixas ficavam quase brancas e com o título sumido (como a de "Neste aparelho", nas Notificações). Corrigido.',
            'No programa do computador, a opção de push (que só existe no celular e no navegador) não aparece mais desligada com um texto vermelho: o aviso no alto já explica como os avisos chegam.',
            'No celular, onde não dá para arrastar arquivos, a foto de perfil, a logo do cliente, o print do suporte, os anexos das conversas e a importação de vídeo dizem "toque para escolher".'] },
  { id: 'v-zzz245', versao: 'zzz245', em: '2026-10-22T22:00:00-03:00',
    titulo: 'Seu perfil agora fica nas Configurações',
    itens: ['Nas Configurações, o perfil ganhou três seções próprias: Perfil (foto e nome), Senha e segurança (senha, verificação em 2 etapas e Google) e Notificações. Cada uma abre no lugar, sem janela por cima.',
            'A foto aparece grande ao lado de onde você escolhe a imagem nova, e o cartão com seu nome no alto do menu muda na hora.',
            '"Meu perfil" no menu da sua foto e o atalho de preferências do sino levam direto para a seção certa.'] },
  { id: 'v-zzz244', versao: 'zzz244', em: '2026-10-22T21:00:00-03:00',
    titulo: 'Toda a administração dentro das Configurações',
    itens: ['"Pessoas e acessos" (contas, senhas, funções e módulos) agora é uma seção das Configurações, no bloco Administração.',
            'Para o super admin, cada área virou uma seção do bloco Super admin: Painel, Pedidos para aprovar, Limites, Segurança, Uso e backup, Avaliações e, para o supremo, Supremo.',
            'Os links antigos (avisos, menu da conta) levam direto para a seção certa das Configurações.',
            'O cartão da sua conta não aparece mais repetido: fica só no alto do menu das Configurações.'] },
  { id: 'v-zzz243', versao: 'zzz243', em: '2026-10-22T20:00:00-03:00',
    titulo: '"Mais" do celular novo e Configurações com a cara da B7',
    itens: ['No celular, o botão "Mais" abre uma tela nova: no topo, o degradê da B7 com sua saudação e o "Meu dia em 30 segundos"; logo abaixo, uma busca para achar qualquer tela pelo nome.',
            'As telas que você mais abre pelo "Mais" aparecem primeiro, em "Usados por você". Os grupos agora têm título e os ícones seguem as cores da B7.',
            'Quem não é administrador também encontra Configurações e Ajuda no "Mais".',
            'Nas Configurações, o cartão da sua conta, os ícones do menu e as chaves ligadas ganharam as cores da B7.'] },
  { id: 'v-zzz242', versao: 'zzz242', em: '2026-10-22T19:00:00-03:00',
    titulo: 'Configurações repaginadas',
    itens: ['As Configurações agora são seções curtas num menu com ícones: Conta, Preferências, Aparência, Abertura e sons, Teleprompter, Apps e TV e Este aparelho.',
            'No celular o menu é a primeira tela: toque numa seção para entrar e em "‹ Configurações" para voltar, como nos ajustes do telefone.',
            'Dentro de cada seção o visual ficou mais limpo: títulos grandes, um cartão com as opções e, à direita, o botão quando a opção faz algo (Sair, Testar, Buscar…) ou só uma setinha quando ela abre outra tela.',
            'O som de notificação e o teste dele agora aparecem para todo mundo, em "Abertura e sons". Em Preferências dá para refazer o tour do B7.'] },
  { id: 'v-zzz239', versao: 'zzz239', em: '2026-10-22T18:00:00-03:00',
    titulo: 'Configurações de cara nova',
    itens: ['No computador, as Configurações agora usam a tela inteira. À esquerda ficam sua conta, a busca e as seções (Geral, Aparência…), cada uma dizendo o que tem dentro. À direita fica a seção aberta, com os grupos lado a lado quando a tela permite.',
            'No celular, a tela ficou mais leve: título e cartão da conta menores, e as seções viraram pílulas que rolam de lado.'] },
  { id: 'v-zzz238', versao: 'zzz238', em: '2026-10-22T17:00:00-03:00',
    titulo: 'Portal do cliente mais fácil de usar',
    itens: ['Ao decidir uma cena, o cliente continua no mesmo ponto do roteiro e o Portal o leva até a próxima cena sem decisão. A barra de baixo mostra quantas cenas ele já decidiu.',
            'Quando a equipe envia uma versão nova enquanto o cliente está olhando a anterior, aparece um aviso com o atalho para a versão nova.',
            'O cliente pode mandar observações também depois de decidir, por exemplo para tirar uma dúvida sobre algo já aprovado.',
            'O que espera há mais tempo aparece primeiro, com "Aguardando você há N dias". As abas mostram quantos itens têm, e a Linha Editorial abre a aprovação de cada conteúdo.'] },
  { id: 'v-zzz236', versao: 'zzz236', em: '2026-10-22T16:00:00-03:00',
    titulo: 'Portal do cliente revisado',
    itens: ['Peças de design enviadas para aprovação agora mostram a arte no Portal. Antes o cliente via só o título. Os botões de decisão só liberam depois que a arte carrega.',
            'No celular, o cliente volta a ver as abas das Aprovações (Pendentes, Ajustes, Aprovados…).',
            'Quando algo não carrega, o Portal diz isso e oferece "Tentar de novo", em vez de mostrar a tela vazia.'] },
  { id: 'v-zzz235', versao: 'zzz235', em: '2026-10-22T15:00:00-03:00',
    titulo: 'Correções',
    itens: ['Trocar de tela com a internet lenta não faz mais a tela anterior aparecer por cima da nova (Produção, Design, Linhas, Aprovações, Gravação, Clientes).',
            'O criativo aberto pelas Publicações do Dia não reabre sozinho depois de fechado.',
            'Prazos de Design de hoje não aparecem mais como atrasados à noite.',
            'O sino de notificações não pula avisos nem volta para o começo enquanto você lê.'] },
  { id: 'v-zzz234', versao: 'zzz234', em: '2026-10-22T14:00:00-03:00',
    titulo: 'Cinco aberturas e cinco telas de carregamento novas',
    itens: ['Aberturas novas: Tinta (gotas de tinta que giram até o logo), Glitch (um terminal que quebra e estoura no logo), Aurora (cortinas de luz no céu), Neon (o letreiro que liga piscando) e Mosaico (quadrados que viram e se abrem no logo). Cada uma tem a sua trilha.',
            'A tela de carregamento (a que aparece ao recarregar) também tem estilos: Relâmpago, Pulso, Órbita, Barra, Brilho e Pontos.',
            'Para escolher: Configurações → Aparência → "Estilo da abertura" e "Tela de carregamento". Ao trocar, toque em "Ver agora" no aviso para ver na hora.'] },
  { id: 'v-zzz233', versao: 'zzz233', em: '2026-10-22T12:00:00-03:00',
    titulo: 'Avisos novos',
    itens: ['Os avisos que aparecem depois de salvar, enviar ou quando algo dá errado ganharam ícone e cor: verde deu certo, vermelho deu erro, âmbar é atenção.',
            'Dá para fechar no ×, ou arrastar para o lado no celular. Com o mouse em cima, o aviso espera você terminar de ler.'] },
  { id: 'v-zzz231', versao: 'zzz231', em: '2026-10-22T11:00:00-03:00',
    titulo: 'Aberturas novas',
    itens: ['Streaming: o logo surge no escuro com duas batidas graves, a câmera mergulha na lâmpada e as faixas de luz abrem direto o sistema.',
            'Hiperespaço: as estrelas viram riscos de luz, vem o clarão do salto e o logo da B7 aparece.',
            'Para escolher a sua: Configurações → Aparência → "Estilo da abertura" (ou deixe em "Padrão do sistema").'] },
  { id: 'v-zzz223', versao: 'zzz223', em: '2026-10-21T18:00:00-03:00', rota: 'suporte',
    titulo: 'Suporte com atendimento na hora',
    itens: ['Abriu uma dúvida ou um problema? O assistente responde na hora, no próprio chamado. Se não resolver, toque em "Falar com uma pessoa" (ou ele mesmo chama alguém da equipe).',
            'Quando resolver, toque em "Resolveu" e dê de 1 a 5 estrelas para o atendimento.',
            'Chamado encerrado não recebe mais mensagens: para outro assunto, é só abrir um novo.'] },
  { id: 'v-zzz218', versao: 'zzz218', em: '2026-10-21T15:00:00-03:00',
    titulo: 'Conta mais segura: verificação em 2 etapas',
    itens: ['Em Meu perfil → Segurança, ligue a verificação em 2 etapas: além da senha, o sistema pede um código de 6 números ao entrar.',
            'Escolha como receber: por e-mail (você cadastra e confirma o seu) ou pelo app autenticador do celular (Google Authenticator, Authy, Microsoft Authenticator).',
            'Marque "Confiar neste aparelho por 30 dias" para não precisar do código toda vez neste computador ou celular.',
            'Quando a administração ligar o Google, dá para vincular a sua conta Google e entrar com um clique pelo navegador.'] },
  { id: 'v-zzz217', versao: 'zzz217', em: '2026-10-21T12:00:00-03:00', irPara: 'suporte',
    titulo: 'Suporte: escreva a dúvida e veja a resposta na hora',
    itens: ['No Suporte, escreva a sua dúvida: as perguntas frequentes e os tutoriais certos aparecem na hora, com "Isso resolveu?".',
            'Não resolveu? Toque em "Perguntar ao assistente" e ele responde ali mesmo.',
            'Ainda não? "Falar com a equipe" abre o chamado já com o que você tentou, para ninguém perguntar de novo.',
            'Administração: nova aba "Perguntas frequentes" na Central, com o que mais resolve, o que a equipe procura e não acha, e "Virar pergunta frequente" em cada chamado.'] },
  { id: 'v-zzz216', versao: 'zzz216', em: '2026-10-17T22:00:00-03:00',
    titulo: 'Pedir acesso pelo sistema',
    itens: ['Se uma tela aparece só para ver, ou você ainda não tem acesso a ela, toque em "Pedir mais acesso" e diga por quê.',
            'A administração recebe o pedido na hora e você recebe um aviso com a resposta.'] },
  { id: 'v-zzz214', versao: 'zzz214', em: '2026-10-17T15:00:00-03:00', rota: 'suporte',
    titulo: 'Suporte de cara nova',
    itens: ['A tela de Suporte ficou mais simples: escolha Problema, Sugestão, Dúvida ou Elogio em um toque e acompanhe seus chamados como conversas.',
            'Antes de abrir um chamado, procure nos tutoriais direto ali.',
            'As Ideias da equipe aparecem na própria tela, para votar.'] },
  { id: 'v-zzz213', versao: 'zzz213', em: '2026-10-17T12:00:00-03:00',
    titulo: 'Tour guiado, dicas e um Suporte mais completo',
    itens: ['Tour de boas-vindas: um passeio de 1 minuto pela tela, do jeito da sua função. Dá para pular e refazer pela Ajuda.',
            'Na primeira vez em cada tela aparece uma dica curta de para que ela serve, com o atalho para o tutorial.',
            'Na Ajuda, a lista “Primeiros passos” se marca sozinha conforme você usa o sistema. Alguns tutoriais ganham vídeo.',
            'Suporte: grave a tela (até 15 s) para mostrar o problema, pergunte ao assistente antes de abrir o chamado e vote nas “Ideias da equipe”.'] },
  { id: 'v-zzz211', versao: 'zzz211', em: '2026-10-17T00:30:00-03:00',
    titulo: 'O assistente agora conhece os tutoriais',
    itens: ['Pergunte ao assistente “como faço…”, “onde fica…” ou “não acho…”: ele responde pelo tutorial certo, com os nomes dos botões iguais aos da tela.',
            'Embaixo da resposta aparece “Abrir tutorial”, que leva direto ao passo a passo completo.',
            'Se nenhum tutorial responder, ele avisa e sugere abrir um chamado no Suporte, em vez de inventar.'] },
  { id: 'v-zzz210', versao: 'zzz210', em: '2026-10-16T23:59:00-03:00',
    titulo: 'Ajuda e Suporte de cara nova',
    itens: ['Ajuda: nova tela inicial com busca grande, sugestões para a sua função e o seu progresso de leitura. Cada tutorial tem índice ao lado, passos que você marca como feitos, “Ir para a tela” e “Este tutorial ajudou?”.',
            'Suporte: números no alto (em aberto, com resposta nova, resolvidos), busca, bolinha nos chamados com novidade e linha do tempo do andamento.',
            'Quando a equipe marca como resolvido, você responde “Isso resolveu?”. Se ainda acontece, dá para reabrir o chamado.',
            'Ao escrever uma dúvida ou problema, o sistema já sugere tutoriais que podem resolver. A tela de suporte se atualiza sozinha.'] },
  { id: 'v-zzz209', versao: 'zzz209', em: '2026-10-16T23:00:00-03:00',
    titulo: 'Ajuda e tutoriais dentro do sistema',
    itens: ['Novo botão “?” no topo, ao lado das conversas: abre o tutorial da tela em que você está.',
            'No menu da sua foto, “Ajuda e tutoriais”: 38 passo a passo, um para cada parte do sistema, com busca. Dá para voltar para a tela em que você estava com um clique.',
            'Não achou o que precisa ou algo está diferente? Os tutoriais têm o atalho para o “Suporte e feedback”.'] },
  { id: 'v-zzz208', versao: 'zzz208', em: '2026-10-16T21:00:00-03:00',
    titulo: 'Suporte e feedback dentro do sistema',
    itens: ['No menu da sua foto, novo item “Suporte e feedback”: relate um problema, mande uma sugestão, tire uma dúvida ou elogie.',
            'Dá para colar um print (Ctrl+V). O chamado leva sozinho a tela, a versão e o aparelho, para a gente resolver mais rápido (você pode desmarcar).',
            'A equipe responde na própria tela e você recebe um aviso no sino a cada resposta e a cada mudança de andamento.'] },
  { id: 'v-zzz207', versao: 'zzz207', em: '2026-10-16T19:00:00-03:00',
    titulo: 'Trends mais inteligentes e pasta de referências',
    itens: ['Trends ganham etiquetas (nicho, assunto, formato) e podem ser só de um cliente. Dá para filtrar por etiqueta.',
            'Em Trends, “Sugerir para” um cliente: o B7 mostra as trends que combinam com a linha editorial dele, da que mais combina para a que menos, e diz por quê.',
            'Escolha várias trends e use “Adicionar à gravação…” — elas entram de uma vez como referência na gravação do cliente.',
            'Na gravação, “Ver todas as referências deste cliente” abre a pasta com as trends usadas e os links da linha editorial.'] },
  { id: 'v-zzz206', versao: 'zzz206', em: '2026-10-16T17:00:00-03:00',
    titulo: 'Dia fixo de gravar e preparação da gravação',
    itens: ['Em Editar cliente, nova opção “Gravação fixa” (toda semana ou todo mês). O sistema cria sozinho a gravação alguns dias antes, uma vez por data.',
            'Cada gravação ganha a “Preparação”: data marcada, linha do mês, roteiros dos Reels, referências decididas e lista montada — com o que falta e quantos dias restam.',
            'Na lista de Gravações, cada gravação que ainda vai acontecer mostra “Preparação 3/5 · em 4 dias” (ou “Tudo pronto”).'] },
  { id: 'v-zzz205', versao: 'zzz205', em: '2026-10-16T15:00:00-03:00',
    titulo: 'Referências da linha editorial vão para a gravação',
    itens: ['Todo link de referência colocado na linha editorial (no conteúdo ou no mês) aparece na gravação do cliente, em “Referências da linha editorial”.',
            'Para cada link, escolha: “Só edição” (quem edita usa de inspiração) ou “Edição e gravação” (também orienta o que vamos gravar). Se o link mudar, volta a pedir a escolha.',
            'No conteúdo da linha, logo abaixo do link, já dá para escolher na hora.'] },
  { id: 'v-zzz202', versao: 'zzz202', em: '2026-10-16T12:00:00-03:00',
    titulo: 'Corretor de texto no WhatsApp e no chat',
    itens: ['Ao enviar uma mensagem no chat de Conversas ou no WhatsApp do programa de Windows, o B7 corrige ortografia e gramática antes de mandar — sem mudar o que você quis dizer.',
            'Dá para ligar e desligar: botão ✨ no chat de Conversas e “Corrigir texto” na barra do WhatsApp. Se a IA estiver fora do ar, a mensagem sai do jeito que você escreveu.'] },
  { id: 'v-zzz201', versao: 'zzz201', em: '2026-10-16T10:00:00-03:00',
    titulo: 'Entregar várias demandas de vídeo de uma vez',
    itens: ['Na Edição de vídeo (Kanban e Lista), segure Ctrl e clique para escolher várias demandas — ou use “Selecionar todas”.',
            'Clique com o botão direito e escolha “Marcar como entregue”: todas as selecionadas viram entregues de uma vez.'] },
  { id: 'v-zzz194', versao: 'zzz194', em: '2026-10-15T18:00:00-03:00',
    titulo: 'IA nas conversas do WhatsApp',
    itens: ['No painel ao lado da conversa, “O que rolou aqui?” resume o grupo: o que o cliente pediu, o que está pendente e o que já foi resolvido.',
            '“Sugerir resposta” escreve uma mensagem para responder o cliente, usando a conversa e o que está pendente no sistema. Você confere, ajusta e envia.'] },
  { id: 'v-zzz188', versao: 'zzz188', em: '2026-10-15T16:00:00-03:00',
    titulo: 'Aprovação do cliente pelo WhatsApp',
    itens: ['Quando o cliente aprova (ou pede ajuste) pelo WhatsApp, clique em “Cliente respondeu” na linha editorial ou no roteiro e registre — sai do “Aguardando cliente”.',
            'O Portal do cliente está pausado: “Enviar para aprovação” só marca a versão como enviada; o envio de verdade é pelo WhatsApp.'] },
  { id: 'v-zzz186', versao: 'zzz186', em: '2026-10-15T15:00:00-03:00',
    titulo: 'WhatsApp: várias artes de uma vez',
    itens: ['Ao enviar uma arte, dá para marcar quais vão e juntar outras do computador — várias de uma vez (a mesma arte em proporções diferentes, por exemplo).',
            'Abrir uma janela do sistema com o WhatsApp aberto não deixa mais o WhatsApp “boiando” claro por cima.',
            'A atualização do programa de Windows fecha o programa sozinha, sem o aviso “Não é possível fechar o Sistema B7”.'] },
  { id: 'v-zzz185', versao: 'zzz185', em: '2026-10-15T14:00:00-03:00',
    titulo: 'Artes direto no WhatsApp',
    itens: ['No programa de Windows, a peça de design tem o botão “Enviar no WhatsApp”: o sistema abre o grupo do cliente, anexa as artes da versão mais nova e escreve a mensagem. Quem aperta enviar é você.',
            'O botão aparece no painel ao lado da conversa e na própria peça, depois de aprovada pela B7.'] },
  { id: 'v-zzz184', versao: 'zzz184', em: '2026-10-15T12:00:00-03:00',
    titulo: 'Painel do WhatsApp de cara nova',
    itens: ['O painel ao lado das conversas ficou mais limpo: cliente em destaque e lista de quem espera resposta com foto e tempo.',
            'Grupo que outra área cuida pode sair do “esperando resposta”: passe o mouse e clique no ×, ou desmarque o aviso dentro do grupo.',
            'Mensagens da equipe (inclusive do comercial) não aparecem mais como cliente esperando.'] },
  { id: 'v-zzz176', versao: 'zzz176', em: '2026-10-15T03:00:00-03:00',
    titulo: 'WhatsApp mais esperto (programa de Windows)',
    itens: ['O sistema reconhece sozinho os grupos de cada cliente pelo nome (“Suporte B7-3X - Infinite Fio” → Infinite Fio). Em “Conferir grupos” você confere uma vez.',
            'Ao lado da conversa, o cartão do cliente: vídeos, artes e gravações pendentes, com atalho para enviar no grupo.',
            '“Possível aprovação”: quando o cliente escreve “aprovado”, “pode postar”, “ficou ótimo”, o cartão avisa e leva à demanda.',
            '“Esperando resposta”: grupos de cliente sem resposta há mais de 15 min aparecem na lista; passou de 1 h, chega um aviso.',
            'Visual novo: cantos arredondados, entrada suave e os avisos do sistema aparecem na frente do WhatsApp.'] },
  { id: 'v-zzz173', versao: 'zzz173', em: '2026-10-15T02:00:00-03:00',
    titulo: 'WhatsApp: tela mais limpa',
    itens: ['Os menus do topo (Criar, avisos, sua conta) não ficam mais cortados atrás do WhatsApp.',
            'Barra nova: liga/desliga da assinatura com o nome editável, tamanho da letra (A− A+), recarregar e desconectar.'] },
  { id: 'v-zzz170', versao: 'zzz170', em: '2026-10-15T01:00:00-03:00',
    titulo: 'WhatsApp dentro do B7',
    itens: ['Novo item “WhatsApp” no menu: no programa de Windows, o WhatsApp abre dentro do sistema (leia o QR Code uma vez) e continua recebendo mensagens enquanto você usa as outras telas.',
            'Assinatura: suas mensagens saem com o seu nome em negrito na primeira linha. Liga, desliga e muda o nome no topo da tela do WhatsApp.',
            'Na demanda de vídeo, “Enviar no WhatsApp”: escolha o vídeo, e o sistema abre o grupo do cliente com o vídeo como documento e a mensagem pronta — você confere e aperta enviar.',
            'Na gravação marcada, “Avisar no WhatsApp” manda dia, hora e local para o grupo do cliente.',
            'Em Editar cliente, novo campo “Grupo do WhatsApp” (o nome do grupo como aparece no WhatsApp).'] },
  { id: 'v-zzz169', versao: 'zzz169', em: '2026-10-14T23:50:00-03:00',
    titulo: 'Assistente, Conversas e cores de cara nova',
    itens: ['Assistente: escolher cliente com busca (os últimos usados aparecem primeiro), histórico com busca e separado por dia, botão de copiar a resposta e “Tentar de novo”.',
            'Conversas: no computador, a lista fica ao lado da conversa; busca, filtro de não lidas, responder uma mensagem, reagir com emoji, editar o que você mandou e arrastar arquivos para enviar.',
            'Aparência: cinco paletas novas, fundos neutros, suaves ou coloridos, cantos retos ou arredondados e tema claro, escuro ou automático — com prévia na hora.',
            'As telas se atualizam mais rápido quando alguém muda algo, e voltam sozinhas se a internet cair.',
            'No programa de Windows, aparece no topo quando há atualização nova — um clique instala.'] },
  { id: 'v-zzz165', versao: 'zzz165', em: '2026-10-14T23:00:00-03:00',
    titulo: 'Tudo ao vivo, arrastar em lote e vídeo só de edição',
    itens: ['As telas se atualizam sozinhas quando alguém da equipe muda algo — sem precisar recarregar.',
            'Na linha editorial, o vídeo pode ser “Gravação e edição” ou “Só edição” (que já vira demanda em Edição de vídeo), e pode ser marcado como meme ou trend, com o link de referência indo junto.',
            'No quadro de Design e de Edição de vídeo, arrastar ficou mais suave; Ctrl ou Shift + clique marca vários cartões para mover juntos.',
            'O histórico das demandas mostra dia e hora de cada passo.',
            'No app Android, dá para escolher a cor do ícone em Configurações → Geral → Aplicativos.'] },
  { id: 'v-zzz164', versao: 'zzz164', em: '2026-10-14T21:00:00-03:00', rota: 'trends',
    titulo: 'Trends: guarde e transforme em roteiro',
    itens: ['Viu uma trend boa? No menu, “Trends” → “Nova trend”: cole o link e dê um nome.',
            '“Usar para um cliente” cria o roteiro numa gravação dele, já com a referência, e abre o editor.',
            'Cada cliente agora diz como trabalhamos com ele: linha editorial, por semana ou só roteiros — e a tela dele mostra só o que usa.'] },
  { id: 'v-zzz163', versao: 'zzz163', em: '2026-10-14T18:00:00-03:00',
    titulo: 'Escolha a cor do seu B7',
    itens: ['Em Configurações → Aparência, toque numa bolinha e o B7 inteiro troca de cor na hora — só para você.',
            'Agora tudo acompanha a cor: menu lateral, cabeçalhos, calendário, botões, brilhos e até os tons de cinza.',
            'Em “Mais opções” dá para escolher qualquer cor pelo código e ver a prévia no claro e no escuro.',
            'Nas Configurações, o campo “Procurar um ajuste” acha qualquer opção sem precisar trocar de aba.'] },
  { id: 'v-zzz135', versao: 'zzz135', em: '2026-10-09T17:30:00-03:00', ia: 'chat',
    titulo: 'Assistente cria várias demandas de uma vez',
    itens: ['Peça “crie 7 demandas para o cliente X, código do 8 ao 14” e ele monta um cartão para cada uma.',
            'Dá para dizer quem é o responsável e de qual gravação é: isso já vai na demanda.',
            'Com mais de uma proposta, o botão “Criar todas” cria tudo de uma vez.'] },
  { id: 'v-zzz134', versao: 'zzz134', em: '2026-10-09T16:00:00-03:00', recurso: 'conversas',
    titulo: 'Conversas da equipe',
    itens: ['O botão de conversa no topo, ao lado do sino, abre o chat interno: fale com qualquer pessoa da equipe sem sair da tela.',
            'Dá para mandar texto, áudio, imagem e arquivo, e colar um print com Ctrl+V.',
            'Você vê quem está online, o visto por último, quando a pessoa está digitando ou gravando áudio, e se a mensagem foi entregue e lida.',
            'Mensagem nova toca um som e chega como aviso no celular, se as notificações estiverem ligadas.'] },
  { id: 'v-zzz131', versao: 'zzz131', em: '2026-10-09T12:00:00-03:00',
    titulo: 'As novidades agora chegam sozinhas',
    itens: ['A cada atualização do B7, este cartão conta o que mudou para você.',
            'Dá para reler tudo em Configurações → Geral → Novidades do B7.'] },
  { id: 'v-zzz128', versao: 'zzz128', em: '2026-10-09T08:30:00-03:00', ia: 'chat',
    titulo: 'Assistente: imagem, roteiro pelo conteúdo e mais rapidez',
    itens: ['Dá para anexar uma imagem ou colar um print (Ctrl+V) na conversa com o assistente.',
            'No conteúdo da linha editorial, “Criar roteiro com IA” já cria o roteiro ligado a ele.',
            'O assistente responde mais rápido e usa o que já foi publicado do cliente como referência de tom.'] },
  { id: 'v-zzz127', versao: 'zzz127', em: '2026-10-09T07:30:00-03:00', ia: 'chat',
    titulo: 'Assistente enxerga mais e propõe mais',
    itens: ['Ele agora vê o andamento do mês, as datas dos próximos dias e os comentários em aberto.',
            'Além de demanda de vídeo, pode propor peça de design, gravação e conteúdo da linha — nada é criado sem você confirmar.',
            'Cada resposta tem o botão Ouvir, e as propostas ficam guardadas na conversa.',
            'Nas Oportunidades, cada ideia tem “Usar na linha”, que já leva título, gancho e legenda.'] },
  { id: 'v-zzz126', versao: 'zzz126', em: '2026-10-08T20:00:00-03:00', ia: 'chat', recurso: 'ia_voz',
    titulo: 'Fale com o assistente',
    itens: ['O microfone no campo de mensagem grava a sua fala e escreve o texto para você.'] },
  { id: 'v-zzz123', versao: 'zzz123', em: '2026-10-08T17:30:00-03:00', rota: 'oportunidades', recurso: 'ia_ideias',
    titulo: 'Ideias de conteúdo nas Oportunidades',
    itens: ['Na folha de cada data, a IA sugere três ideias de conteúdo para o cliente escolhido.',
            'A ficha do cliente ganhou “Memória da IA”: o que você anotar ali, a IA passa a respeitar.'] },
  { id: 'v-zzz121', versao: 'zzz121', em: '2026-10-08T15:30:00-03:00', rota: 'oportunidades', recurso: 'hoje_dia',
    titulo: 'Hoje é dia de…',
    itens: ['Toda manhã chega um aviso com as datas relevantes do dia.',
            'A data do dia também aparece no topo do Painel.'] },
  { id: 'v-zzz120', versao: 'zzz120', em: '2026-10-08T13:00:00-03:00', funcao: 'videomaker',
    titulo: 'Painel do videomaker mais completo',
    itens: ['Entraram a fila por etapa, os próximos 14 dias, as últimas entregas e o relógio.',
            'Ele se atualiza sozinho, para deixar aberto na tela.'] }
];
